#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Адрес 0x27, 16 символов, 2 строки
LiquidCrystal_I2C LCD(0x27, 16, 2);

// Разносим I2C, чтобы оставить GPIO 4 свободным для кнопки/реле
#define I2C_SDA 5
#define I2C_SCL 6

void setup() {
  Serial.begin(115200);

  Wire.begin(I2C_SDA, I2C_SCL);

  LCD.init();
  LCD.backlight();

  // Очищаем и выводим текст
  LCD.clear();
  LCD.setCursor(2, 0);   // немного левее центра
  LCD.print("I LOVE MY MOM");
}

void loop() {
}
